module Mux_2x1_NBits #(
    parameter Bits = 2
)
(
    input [0:0] sel,
    input [(Bits - 1):0] in_0,
    input [(Bits - 1):0] in_1,
    output reg [(Bits - 1):0] out
);
    always @ (*) begin
        case (sel)
            1'h0: out = in_0;
            1'h1: out = in_1;
            default:
                out = 'h0;
        endcase
    end
endmodule

module DIG_BitExtenderSingle #(
    parameter outputBits = 2
)
(
    input in,
    output [(outputBits - 1):0] out
);
    assign out = {outputBits{in}};
endmodule



module DIG_RAMDualAccess
#(
    parameter Bits = 8,
    parameter AddrBits = 4
)
(
    input C, // Clock signal
    input ld,
    input [(AddrBits-1):0] \1A ,
    input [(AddrBits-1):0] \2A ,
    input [(Bits-1):0] \1Din ,
    input str,
    output [(Bits-1):0] \1D ,
    output [(Bits-1):0] \2D
);
    // CAUTION: uses distributed RAM
    reg [(Bits-1):0] memory [0:((1 << AddrBits)-1)];

    assign \1D = ld? memory[\1A ] : 'hz;
    assign \2D = memory[\2A ];

    always @ (posedge C) begin
        if (str)
            memory[\1A ] <= \1Din ;
    end

endmodule



module RAM_256KB (
  input [15:0] INSAddressIn,
  input [5:0] ByteSelect,
  input [15:0] AddressIn,
  input [31:0] Din,
  input We,
  input Clock,
  output [31:0] Dout,
  output [31:0] INSout
);
  wire [3:0] s0;
  wire s1;
  wire s2;
  wire s3;
  wire s4;
  wire [7:0] s5;
  wire [7:0] s6;
  wire [7:0] s7;
  wire [7:0] s8;
  wire [3:0] s9;
  wire [7:0] s10;
  wire [7:0] s11;
  wire [7:0] s12;
  wire [7:0] s13;
  wire [7:0] s14;
  wire [7:0] s15;
  wire [7:0] s16;
  wire [7:0] s17;
  DIG_BitExtenderSingle #(
    .outputBits(4)
  )
  DIG_BitExtenderSingle_i0 (
    .in( We ),
    .out( s9 )
  );
  assign s5 = Din[7:0];
  assign s6 = Din[15:8];
  assign s7 = Din[23:16];
  assign s8 = Din[31:24];
  assign s0 = (s9 & ByteSelect[3:0]);
  assign s1 = s0[0];
  assign s2 = s0[1];
  assign s3 = s0[2];
  assign s4 = s0[3];
  // Byte 2
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i1 (
    .str( s3 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s7 ),
    .\2A ( INSAddressIn ),
    .\1D ( s12 ),
    .\2D ( s14 )
  );
  // Byte 3
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i2 (
    .str( s4 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s8 ),
    .\2A ( INSAddressIn ),
    .\1D ( s13 ),
    .\2D ( s15 )
  );
  // Byte 0
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i3 (
    .str( s1 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s5 ),
    .\2A ( INSAddressIn ),
    .\1D ( s10 ),
    .\2D ( s16 )
  );
  // Byte 1
  DIG_RAMDualAccess #(
    .Bits(8),
    .AddrBits(16)
  )
  DIG_RAMDualAccess_i4 (
    .str( s2 ),
    .C( Clock ),
    .ld( 1'b1 ),
    .\1A ( AddressIn ),
    .\1Din ( s6 ),
    .\2A ( INSAddressIn ),
    .\1D ( s11 ),
    .\2D ( s17 )
  );
  assign Dout[7:0] = s10;
  assign Dout[15:8] = s11;
  assign Dout[23:16] = s12;
  assign Dout[31:24] = s13;
  assign INSout[7:0] = s16;
  assign INSout[15:8] = s17;
  assign INSout[23:16] = s14;
  assign INSout[31:24] = s15;
endmodule

