  )
  Mux_2x1_NBits_i13 (
    .sel( s9 ),
    .in_0( s10 ),
    .in_1( s4 ),
    .out( INSout )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i14 (
    .sel( s12 ),
    .in_0( s8 ),
    .in_1( DrIO ),
