  assign s5 = (A & s0);
  assign s6 = (A | s0);
  assign s7 = (A ^ s0);
  mul mul_i3 (
    .A( A ),
    .B( s0 ),
    .As( s27 ),
    .Bs( s13 ),
    .L( s21 ),
    .H( s22 )
