module DIG_RegisterFile
#(
    parameter Bits = 8,
    parameter AddrBits = 4
)
(
    input [(Bits-1):0] Din,
    input we,
    input [(AddrBits-1):0] Rw,
    input C,
    input [(AddrBits-1):0] Ra,
    input [(AddrBits-1):0] Rb,
    output [(Bits-1):0] Da,
    output [(Bits-1):0] Db
);

    reg [(Bits-1):0] memory[0:((1 << AddrBits)-1)];

    assign Da = memory[Ra];
    assign Db = memory[Rb];

    always @ (posedge C) begin
        if (we)
            memory[Rw] <= Din;
    end
endmodule


module Registers (
  input clk,
  input [31:0] Din,
  input We,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  output [31:0] rs1O,
  output [31:0] rs2O
);
  wire s0;
  wire [31:0] s1;
  wire [31:0] s2;
  wire s3;
  wire s4;
  assign s3 = ~ (rs1[0] | rs1[1] | rs1[2] | rs1[3] | rs1[4]);
  assign s4 = ~ (rs2[0] | rs2[1] | rs2[2] | rs2[3] | rs2[4]);
  assign s0 = (We & (rd[0] | rd[1] | rd[2] | rd[3] | rd[4]));
  // Registers 1-31
  DIG_RegisterFile #(
    .Bits(32),
    .AddrBits(5)
  )
  DIG_RegisterFile_i0 (
    .Din( Din ),
    .we( s0 ),
    .Rw( rd ),
    .C( clk ),
    .Ra( rs1 ),
    .Rb( rs2 ),
    .Da( s1 ),
    .Db( s2 )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i1 (
    .sel( s3 ),
    .in_0( s1 ),
    .in_1( 32'b0 ),
    .out( rs1O )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i2 (
    .sel( s4 ),
    .in_0( s2 ),
    .in_1( 32'b0 ),
    .out( rs2O )
  );
endmodule

module Mux_4x1
(
    input [1:0] sel,
    input in_0,
    input in_1,
    input in_2,
    input in_3,
    output reg out
);
    always @ (*) begin
        case (sel)
            2'h0: out = in_0;
            2'h1: out = in_1;
            2'h2: out = in_2;
            2'h3: out = in_3;
            default:
                out = 'h0;
        endcase
    end
endmodule


module PcInSelector (
  input [1:0] BranchIns, // 00: BEQ
                         // 01: BNE
                         // 10: BLT
                         // 11: BGE
  input [1:0] PcInSel,
  input [1:0] Flags, // Z,LessThan
  input [31:0] ALU,
  input [31:0] AdAdd,
  input [31:0] \PC+4 ,
  output [31:0] PC
);
  wire [31:0] s0;
  wire s1;
  wire s2;
  wire s3;
  wire s4;
  wire s5;
  assign s4 = Flags[0];
  assign s2 = Flags[1];
  assign s3 = ~ s2;
  assign s5 = ~ s4;
  Mux_4x1 Mux_4x1_i0 (
    .sel( BranchIns ),
    .in_0( s2 ),
    .in_1( s3 ),
    .in_2( s4 ),
    .in_3( s5 ),
    .out( s1 )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i1 (
    .sel( s1 ),
    .in_0( \PC+4  ),
    .in_1( AdAdd ),
    .out( s0 )
  );
  Mux_4x1_NBits #(
    .Bits(32)
  )
  Mux_4x1_NBits_i2 (
    .sel( PcInSel ),
    .in_0( \PC+4  ),
    .in_1( AdAdd ),
    .in_2( ALU ),
    .in_3( s0 ),
    .out( PC )
  );
endmodule

module DIG_Register_BUS #(
    parameter Bits = 1
)
(
    input C,
    input en,
    input [(Bits - 1):0]D,
    output [(Bits - 1):0]Q
);

    reg [(Bits - 1):0] state = 'h0;

    assign Q = state;

    always @ (posedge C) begin
        if (en)
            state <= D;
   end
endmodule

module ProgramCounter (
  input Clock,
  input [31:0] Din,
  output [31:0] Dout,
  output [31:0] \PC+4 
);
  wire [31:0] s0;
  wire [31:0] Dout_temp;
  assign s0[0] = 1'b0;
  assign s0[31:1] = Din[31:1];
  DIG_Register_BUS #(
    .Bits(32)
  )
  DIG_Register_BUS_i0 (
    .D( s0 ),
    .C( Clock ),
    .en( 1'b1 ),
    .Q( Dout_temp )
  );
  DIG_Add #(
    .Bits(32)
  )
  DIG_Add_i1 (
    .a( Dout_temp ),
    .b( 32'b100 ),
    .c_i( 1'b0 ),
    .s( \PC+4  )
  );
  assign Dout = Dout_temp;
endmodule

